import * as THREE from "three";

export const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
export const lerp = (a, b, t) => a + (b - a) * t;
export const invLerp = (a, b, v) => (b === a ? 0 : (v - a) / (b - a));

export function smoothstep(e0, e1, x) {
  const t = clamp((x - e0) / (e1 - e0 || 1e-6), 0, 1);
  return t * t * (3 - 2 * t);
}

/** Framerate independent exponential approach. */
export function damp(current, target, lambda, dt) {
  return lerp(current, target, 1 - Math.exp(-lambda * dt));
}

/** Cheap deterministic 1D value noise (smooth, no allocations). */
export function vnoise1(x) {
  const i = Math.floor(x);
  const f = x - i;
  const u = f * f * (3 - 2 * f);
  return lerp(hash1(i), hash1(i + 1), u);
}

export function hash1(n) {
  const s = Math.sin(n * 127.1 + 311.7) * 43758.5453;
  return s - Math.floor(s);
}

/** Fractal noise built from vnoise1 — used for handheld camera drift. */
export function fbm1(x, octaves = 3) {
  let sum = 0;
  let amp = 0.5;
  let freq = 1;
  for (let i = 0; i < octaves; i++) {
    sum += amp * vnoise1(x * freq + i * 17.3);
    freq *= 2.03;
    amp *= 0.5;
  }
  return sum;
}

export const TAU = Math.PI * 2;

const _v = new THREE.Vector3();

/**
 * Tube along a curve with a radius that varies along its length
 * (three's TubeGeometry only supports a constant radius).
 */
export function taperedTube(curve, tubularSegments, radiusFn, radialSegments = 10) {
  const frames = curve.computeFrenetFrames(tubularSegments, false);
  const positions = [];
  const normals = [];
  const uvs = [];
  const indices = [];

  for (let i = 0; i <= tubularSegments; i++) {
    const u = i / tubularSegments;
    const r = radiusFn(u);
    const P = curve.getPoint(u, _v);
    const N = frames.normals[i];
    const B = frames.binormals[i];

    for (let j = 0; j <= radialSegments; j++) {
      const v = (j / radialSegments) * TAU;
      const sin = Math.sin(v);
      const cos = -Math.cos(v);

      const nx = cos * N.x + sin * B.x;
      const ny = cos * N.y + sin * B.y;
      const nz = cos * N.z + sin * B.z;

      normals.push(nx, ny, nz);
      positions.push(P.x + r * nx, P.y + r * ny, P.z + r * nz);
      uvs.push(i / tubularSegments, j / radialSegments);
    }
  }

  for (let j = 1; j <= tubularSegments; j++) {
    for (let i = 1; i <= radialSegments; i++) {
      const a = (radialSegments + 1) * (j - 1) + (i - 1);
      const b = (radialSegments + 1) * j + (i - 1);
      const c = (radialSegments + 1) * j + i;
      const d = (radialSegments + 1) * (j - 1) + i;
      indices.push(a, b, d, b, c, d);
    }
  }

  const geo = new THREE.BufferGeometry();
  geo.setIndex(indices);
  geo.setAttribute("position", new THREE.Float32BufferAttribute(positions, 3));
  geo.setAttribute("normal", new THREE.Float32BufferAttribute(normals, 3));
  geo.setAttribute("uv", new THREE.Float32BufferAttribute(uvs, 2));
  geo.computeBoundingSphere();
  return geo;
}

/** Bake a per-vertex colour ramp into a geometry (used for wings, tail, board). */
export function paintVertices(geometry, colorFn) {
  const pos = geometry.attributes.position;
  const colors = new Float32Array(pos.count * 3);
  const c = new THREE.Color();
  for (let i = 0; i < pos.count; i++) {
    c.setRGB(1, 1, 1);
    colorFn(c, pos.getX(i), pos.getY(i), pos.getZ(i), i);
    colors[i * 3] = c.r;
    colors[i * 3 + 1] = c.g;
    colors[i * 3 + 2] = c.b;
  }
  geometry.setAttribute("color", new THREE.Float32BufferAttribute(colors, 3));
  return geometry;
}

/**
 * Build a THREE.Shape from a closed list of points using centripetal
 * Catmull-Rom sampling — handy for organic silhouettes.
 */
export function smoothShape(points, samples = 12, closed = true) {
  const pts = points.map((p) => new THREE.Vector2(p[0], p[1]));
  const curve = new THREE.SplineCurve(pts);
  curve.closed = closed;
  const shape = new THREE.Shape();
  const out = curve.getSpacedPoints(samples * pts.length);
  shape.moveTo(out[0].x, out[0].y);
  for (let i = 1; i < out.length; i++) shape.lineTo(out[i].x, out[i].y);
  return shape;
}

/**
 * The ocean is one analytic height field: a sum of directional sine components.
 * The very same parameter list is evaluated on the CPU (so the board, the wake
 * and the camera sit exactly on the rendered surface) and code-generated into
 * GLSL (so the surface itself is displaced + shaded).
 */

export const GRAVITY = 9.81;

/** angle = travel direction in the XZ plane. ~PI/2 means the swell runs toward +Z,
 *  so crests line up along X — which is the direction our pelican travels. */
export const SWELL = [
  { angle: 1.46, wavelength: 52.0, amp: 0.72, speed: 1.0 },
  { angle: 1.63, wavelength: 31.0, amp: 0.46, speed: 1.0 },
  { angle: 1.34, wavelength: 19.5, amp: 0.3, speed: 1.03 },
  { angle: 1.78, wavelength: 12.4, amp: 0.17, speed: 1.06 },
  { angle: 1.16, wavelength: 7.6, amp: 0.085, speed: 1.1 },
  { angle: 1.94, wavelength: 4.6, amp: 0.045, speed: 1.14 },
];

/** Short wind chop. Only used to perturb the shading normal (never displaced),
 *  which keeps the silhouette cheap while the surface still sparkles up close. */
export const CHOP = [
  { angle: 0.62, wavelength: 1.62, amp: 0.024, speed: 1.25 },
  { angle: 2.14, wavelength: 1.03, amp: 0.015, speed: 1.4 },
  { angle: 4.21, wavelength: 0.66, amp: 0.009, speed: 1.55 },
  { angle: 5.61, wavelength: 0.41, amp: 0.005, speed: 1.7 },
];

export const MAX_HEIGHT = SWELL.reduce((s, w) => s + w.amp, 0);

export function expand(wave) {
  const k = (Math.PI * 2) / wave.wavelength;
  return {
    amp: wave.amp,
    kx: Math.cos(wave.angle) * k,
    kz: Math.sin(wave.angle) * k,
    omega: Math.sqrt(GRAVITY * k) * wave.speed,
  };
}

const SWELL_P = SWELL.map(expand);
const CHOP_P = CHOP.map(expand);

const n = (v) => v.toFixed(6);

/** --- CPU side ------------------------------------------------------- */

export function oceanHeight(x, z, t) {
  let h = 0;
  for (let i = 0; i < SWELL_P.length; i++) {
    const w = SWELL_P[i];
    h += w.amp * Math.sin(w.kx * x + w.kz * z - w.omega * t);
  }
  return h;
}

/** Returns [dh/dx, dh/dz]. */
export function oceanSlope(x, z, t, out) {
  let dx = 0;
  let dz = 0;
  for (let i = 0; i < SWELL_P.length; i++) {
    const w = SWELL_P[i];
    const c = w.amp * Math.cos(w.kx * x + w.kz * z - w.omega * t);
    dx += c * w.kx;
    dz += c * w.kz;
  }
  out = out || [0, 0];
  out[0] = dx;
  out[1] = dz;
  return out;
}

const _slope = [0, 0];

/** Unit surface normal, cached vector (do not hold onto it). */
export function oceanNormal(x, z, t, target) {
  oceanSlope(x, z, t, _slope);
  return target.set(-_slope[0], 1, -_slope[1]).normalize();
}

/** --- GLSL side ------------------------------------------------------ */

function glslComponents(list) {
  return list.map((w) => {
    const p = expand(w);
    return {
      dot: `dot(vec2(${n(p.kx)}, ${n(p.kz)}), p)`,
      amp: n(p.amp),
      kx: n(p.kx),
      kz: n(p.kz),
      omega: n(p.omega),
    };
  });
}

export const OCEAN_GLSL = /* glsl */ `
float oceanHeight(vec2 p, float t) {
  float h = 0.0;
${glslComponents(SWELL)
  .map((c) => `  h += ${c.amp} * sin(${c.dot} - ${c.omega} * t);`)
  .join("\n")}
  return h;
}

vec2 oceanSlope(vec2 p, float t) {
  vec2 d = vec2(0.0);
${glslComponents(SWELL)
  .map(
    (c, i) =>
      `  float c${i} = ${c.amp} * cos(${c.dot} - ${c.omega} * t);\n  d += vec2(${c.kx}, ${c.kz}) * c${i};`
  )
  .join("\n")}
  return d;
}

vec2 chopSlope(vec2 p, float t) {
  vec2 d = vec2(0.0);
${glslComponents(CHOP)
  .map(
    (c, i) =>
      `  float k${i} = ${c.amp} * cos(${c.dot} - ${c.omega} * t);\n  d += vec2(${c.kx}, ${c.kz}) * k${i};`)
  .join("\n")}
  return d;
}
`;

import * as THREE from "three";

/** All textures in this project are generated in code (no external assets). */

function canvas(size) {
  const c = document.createElement("canvas");
  c.width = size.w || size;
  c.height = size.h || size;
  return c;
}

function finish(c, { repeat = 1, srgb = false, aniso = 4 } = {}) {
  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(repeat, repeat);
  tex.anisotropy = aniso;
  if (srgb) tex.colorSpace = THREE.SRGBColorSpace;
  tex.needsUpdate = true;
  return tex;
}

/** Soft round puff — spray droplets, mist, wake foam. */
export function softDotTexture() {
  const c = canvas(128);
  const g = c.getContext("2d");
  const grd = g.createRadialGradient(64, 64, 0, 64, 64, 64);
  grd.addColorStop(0.0, "rgba(255,255,255,1)");
  grd.addColorStop(0.25, "rgba(255,255,255,0.82)");
  grd.addColorStop(0.55, "rgba(255,255,255,0.28)");
  grd.addColorStop(1.0, "rgba(255,255,255,0)");
  g.fillStyle = grd;
  g.fillRect(0, 0, 128, 128);
  return finish(c);
}

/** Contact shadow blob under the board. */
export function blobShadowTexture() {
  const c = canvas({ w: 256, h: 256 });
  const g = c.getContext("2d");
  const grd = g.createRadialGradient(128, 128, 0, 128, 128, 128);
  grd.addColorStop(0.0, "rgba(0,0,0,0.85)");
  grd.addColorStop(0.45, "rgba(0,0,0,0.45)");
  grd.addColorStop(0.8, "rgba(0,0,0,0.10)");
  grd.addColorStop(1.0, "rgba(0,0,0,0)");
  g.fillStyle = grd;
  g.fillRect(0, 0, 256, 256);
  return finish(c);
}

/** Overlapping feather scallops — used as a bump map so plumage catches light. */
export function featherBumpTexture() {
  const c = canvas({ w: 256, h: 256 });
  const g = c.getContext("2d");
  g.fillStyle = "#7d7d7d";
  g.fillRect(0, 0, 256, 256);

  const rows = 16;
  const cols = 8;
  for (let r = 0; r < rows; r++) {
    const y = (r / rows) * 256;
    const off = (r % 2) * (256 / cols) * 0.5;
    for (let i = -1; i <= cols; i++) {
      const x = off + (i / cols) * 256 + (256 / cols) * 0.5;
      const w = 256 / cols;
      const grd = g.createLinearGradient(x - w * 0.5, y, x + w * 0.5, y + 256 / rows);
      grd.addColorStop(0.0, "rgba(232,232,232,1)");
      grd.addColorStop(0.55, "rgba(150,150,150,1)");
      grd.addColorStop(1.0, "rgba(58,58,58,1)");
      g.fillStyle = grd;
      g.beginPath();
      g.ellipse(x, y + 256 / rows * 0.55, w * 0.52, (256 / rows) * 0.62, 0, Math.PI, 0);
      g.closePath();
      g.fill();
      g.strokeStyle = "rgba(30,30,30,0.55)";
      g.lineWidth = 1.4;
      g.stroke();
    }
  }
  // fine barb streaks
  g.globalAlpha = 0.14;
  g.strokeStyle = "#ffffff";
  g.lineWidth = 1;
  for (let i = 0; i < 420; i++) {
    const x = Math.random() * 256;
    const y = Math.random() * 256;
    g.beginPath();
    g.moveTo(x, y);
    g.lineTo(x + (Math.random() - 0.5) * 5, y + 3 + Math.random() * 5);
    g.stroke();
  }
  g.globalAlpha = 1;
  return finish(c, { repeat: 3 });
}

/** Fine speckle for resin / deck texture (roughness map). */
export function speckleTexture(base = "#8a8a8a", dots = "#3a3a3a") {
  const c = canvas({ w: 128, h: 128 });
  const g = c.getContext("2d");
  g.fillStyle = base;
  g.fillRect(0, 0, 128, 128);
  g.fillStyle = dots;
  for (let i = 0; i < 900; i++) {
    g.globalAlpha = 0.05 + Math.random() * 0.2;
    const s = Math.random() * 1.8 + 0.4;
    g.fillRect(Math.random() * 128, Math.random() * 128, s, s);
  }
  g.globalAlpha = 1;
  return finish(c, { repeat: 4 });
}

