import * as THREE from "three";
import { GLSL_SKY_COMMON } from "./glsl-common.js";

const VERT = /* glsl */ `
varying vec3 vDir;
void main() {
  vDir = position;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}
`;

const FRAG = /* glsl */ `
uniform float uTime;
uniform vec3 uSunDir;
uniform vec3 uSunColor;
uniform vec3 uZenith;
uniform vec3 uHorizon;
uniform vec3 uSeaHaze;
uniform vec3 uCloudLit;
uniform vec3 uCloudShade;
varying vec3 vDir;

${GLSL_SKY_COMMON}

float cloudLayer(vec2 cp, float t, float scale, float speed) {
  float n = fbm(cp * scale + vec2(t * speed, t * speed * 0.35));
  float n2 = fbm(cp * scale * 2.7 - vec2(t * speed * 1.6, t * speed * 0.5));
  return smoothstep(0.44, 0.86, n * 0.78 + n2 * 0.34);
}

void main() {
  vec3 d = normalize(vDir);
  float y = d.y;

  // ---- atmosphere gradient
  vec3 col = mix(uHorizon, uZenith, pow(clamp(y, 0.0, 1.0), 0.42));
  // warm band sitting right on the horizon
  col = mix(col, uHorizon * 1.10 + uSunColor * 0.22, exp(-abs(y) * 16.0) * 0.55);
  // below the horizon line: hazy sea mist
  col = mix(uSeaHaze, col, smoothstep(-0.05, 0.012, y));

  // ---- sun
  float sd = max(dot(d, uSunDir), 0.0);
  col += uSunColor * pow(sd, 2400.0) * 26.0;   // disc
  col += uSunColor * pow(sd, 220.0) * 3.4;     // corona
  col += uSunColor * pow(sd, 22.0) * 0.42;     // inner glow
  col += uSunColor * pow(sd, 4.5) * 0.13;      // wide bloom

  // ---- two drifting cloud decks projected onto planes above the viewer
  if (y > 0.004) {
    float t = uTime * 0.55;
    vec2 cp = d.xz / (y + 0.055);

    float high = cloudLayer(cp, t, 0.030, 0.010);
    float low = cloudLayer(cp + vec2(240.0, -180.0), t, 0.085, 0.020);
    low *= smoothstep(0.02, 0.30, y);
    high *= smoothstep(0.01, 0.16, y);

    float cover = clamp(high * 0.95 + low * 0.55, 0.0, 1.0);
    float lit = 0.42 + 0.58 * pow(max(dot(d, uSunDir), 0.0), 2.2);
    float density = clamp(high * 0.7 + low * 0.9, 0.0, 1.0);
    vec3 cloudCol = mix(uCloudShade, uCloudLit, lit);
    cloudCol = mix(cloudCol, uCloudShade * 0.82, density * (1.0 - lit) * 0.7);
    // silver lining when looking toward the sun
    cloudCol += uSunColor * pow(sd, 9.0) * cover * 0.35;
    col = mix(col, cloudCol, cover * 0.9);
  }

  gl_FragColor = vec4(col, 1.0);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}
`;

export const SKY_COLORS = {
  zenith: new THREE.Color("#2d63ab"),
  horizon: new THREE.Color("#ffc98d"),
  seaHaze: new THREE.Color("#e7b98d"),
  cloudLit: new THREE.Color("#fff2dd"),
  cloudShade: new THREE.Color("#9aa6bd"),
  sun: new THREE.Color("#ffe2b0"),
};

export function createSky() {
  const geometry = new THREE.SphereGeometry(1700, 64, 40);
  const material = new THREE.ShaderMaterial({
    uniforms: {
      uTime: { value: 0 },
      uSunDir: { value: new THREE.Vector3(0, 1, 0) },
      uSunColor: { value: SKY_COLORS.sun },
      uZenith: { value: SKY_COLORS.zenith },
      uHorizon: { value: SKY_COLORS.horizon },
      uSeaHaze: { value: SKY_COLORS.seaHaze },
      uCloudLit: { value: SKY_COLORS.cloudLit },
      uCloudShade: { value: SKY_COLORS.cloudShade },
    },
    vertexShader: VERT,
    fragmentShader: FRAG,
    side: THREE.BackSide,
    depthWrite: false,
    fog: false,
  });

  const mesh = new THREE.Mesh(geometry, material);
  mesh.frustumCulled = false;
  mesh.renderOrder = -10;

  return {
    mesh,
    material,
    update(t, sunDir) {
      material.uniforms.uTime.value = t;
      if (sunDir) material.uniforms.uSunDir.value.copy(sunDir);
    },
  };
}

/** GLSL helpers shared by the ocean and sky shaders. */
export const GLSL_SKY_COMMON = /* glsl */ `
float hash21(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}
float vnoise(vec2 p) {
  vec2 i = floor(p), f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash21(i);
  float b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0));
  float d = hash21(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
float fbm(vec2 p) {
  float s = 0.0, a = 0.55;
  for (int i = 0; i < 4; i++) {
    s += a * vnoise(p);
    p = p * 2.07 + vec2(11.3, 7.7);
    a *= 0.5;
  }
  return s;
}
vec3 skyRadiance(vec3 dir, vec3 sunDir, vec3 zenith, vec3 horizon, vec3 sunColor) {
  float y = clamp(dir.y, 0.0, 1.0);
  vec3 c = mix(horizon, zenith, pow(y, 0.5));
  float sd = max(dot(normalize(dir), sunDir), 0.0);
  c += sunColor * pow(sd, 260.0) * 6.0;
  c += sunColor * pow(sd, 14.0) * 0.30;
  return c;
}
`;

