import * as THREE from "three";
import { GLSL_SKY_COMMON } from "./glsl-common.js";
import { oceanHeight } from "./waves.js";
import { lerp, clamp, smoothstep } from "./util.js";

/* ------------------------------------------------------------------ spray */

const SPRAY_VERT = /* glsl */ `
attribute float aSize;
attribute float aAlpha;
uniform float uScale;
varying float vAlpha;
void main() {
  vAlpha = aAlpha;
  vec4 mv = modelViewMatrix * vec4(position, 1.0);
  gl_PointSize = max(1.0, aSize * uScale / max(0.05, -mv.z));
  gl_Position = projectionMatrix * mv;
}
`;

const SPRAY_FRAG = /* glsl */ `
uniform sampler2D uTex;
uniform vec3 uTint;
varying float vAlpha;
void main() {
  vec4 tex = texture2D(uTex, gl_PointCoord);
  float a = tex.a * vAlpha;
  if (a < 0.012) discard;
  gl_FragColor = vec4(tex.rgb * uTint, a);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}
`;

export function createSpray({ texture, count = 700 }) {
  const positions = new Float32Array(count * 3);
  const sizes = new Float32Array(count);
  const alphas = new Float32Array(count);
  const vel = new Float32Array(count * 3);
  const life = new Float32Array(count);
  const maxLife = new Float32Array(count);
  const baseSize = new Float32Array(count);

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute("position", new THREE.BufferAttribute(positions, 3));
  geometry.setAttribute("aSize", new THREE.BufferAttribute(sizes, 1));
  geometry.setAttribute("aAlpha", new THREE.BufferAttribute(alphas, 1));
  geometry.boundingSphere = new THREE.Sphere(new THREE.Vector3(), 60);

  const material = new THREE.ShaderMaterial({
    uniforms: {
      uTex: { value: texture },
      uScale: { value: 600 },
      uTint: { value: new THREE.Color("#fffaf0") },
    },
    vertexShader: SPRAY_VERT,
    fragmentShader: SPRAY_FRAG,
    transparent: true,
    depthWrite: false,
  });

  const points = new THREE.Points(geometry, material);
  points.frustumCulled = false;
  points.renderOrder = 3;

  let cursor = 0;

  function emit(o) {
    const i = cursor;
    cursor = (cursor + 1) % count;
    const i3 = i * 3;
    positions[i3] = o.x;
    positions[i3 + 1] = o.y;
    positions[i3 + 2] = o.z;
    const s = o.speed;
    vel[i3] = (o.dx + (Math.random() - 0.5) * o.spread) * s;
    vel[i3 + 1] = (o.dy + Math.random() * o.spread * 0.9) * s;
    vel[i3 + 2] = (o.dz + (Math.random() - 0.5) * o.spread) * s;
    maxLife[i] = life[i] = o.life * (0.65 + Math.random() * 0.7);
    baseSize[i] = o.size * (0.55 + Math.random() * 0.9);
    sizes[i] = baseSize[i];
    alphas[i] = o.alpha === undefined ? 0.9 : o.alpha;
  }

  function update(dt, time) {
    for (let i = 0; i < count; i++) {
      if (life[i] <= 0) {
        if (alphas[i] !== 0) {
          alphas[i] = 0;
          sizes[i] = 0;
        }
        continue;
      }
      life[i] -= dt;
      const i3 = i * 3;
      // gravity + drag + a little wind
      vel[i3 + 1] -= 9.2 * dt;
      const drag = Math.exp(-1.9 * dt);
      vel[i3] *= drag;
      vel[i3 + 1] *= drag;
      vel[i3 + 2] *= drag;
      positions[i3] += vel[i3] * dt;
      positions[i3 + 1] += vel[i3 + 1] * dt;
      positions[i3 + 2] += vel[i3 + 2] * dt;

      const k = clamp(life[i] / maxLife[i], 0, 1);
      alphas[i] = Math.pow(k, 0.7) * 0.95;
      sizes[i] = baseSize[i] * (1 + (1 - k) * 1.5);

      // dissolve on contact with the sea
      const surf = oceanHeight(positions[i3], positions[i3 + 2], time);
      if (positions[i3 + 1] < surf + 0.005 && vel[i3 + 1] < 0) {
        life[i] = Math.min(life[i], 0.12);
      }
    }
    geometry.attributes.position.needsUpdate = true;
    geometry.attributes.aSize.needsUpdate = true;
    geometry.attributes.aAlpha.needsUpdate = true;
  }

  return {
    points,
    material,
    emit,
    update,
    setScale(h, fov) {
      material.uniforms.uScale.value = h / (2 * Math.tan((fov * Math.PI) / 360));
    },
  };
}

/* ------------------------------------------------------------------- wake */

const WAKE_VERT = /* glsl */ `
attribute float aAge;
attribute float aSide;
varying float vAge;
varying float vSide;
varying vec3 vWorld;
void main() {
  vAge = aAge;
  vSide = aSide;
  vec4 wp = modelMatrix * vec4(position, 1.0);
  vWorld = wp.xyz;
  gl_Position = projectionMatrix * viewMatrix * wp;
}
`;

const WAKE_FRAG = /* glsl */ `
uniform float uTime;
uniform vec3 uFoam;
uniform vec3 uShade;
varying float vAge;
varying float vSide;
varying vec3 vWorld;
${GLSL_SKY_COMMON}
void main() {
  float dist = length(cameraPosition - vWorld);
  float n = fbm(vWorld.xz * 3.1 + vec2(uTime * 0.35, -uTime * 0.22));
  float n2 = fbm(vWorld.xz * 9.0 - vec2(uTime * 0.6, uTime * 0.3));
  float body = smoothstep(0.30, 0.85, n * 0.7 + n2 * 0.5);
  float along = pow(1.0 - clamp(vAge, 0.0, 1.0), 1.35);
  float across = smoothstep(1.0, 0.25, abs(vSide));
  float a = body * along * across;
  a *= smoothstep(420.0, 90.0, dist);
  if (a < 0.01) discard;
  vec3 col = mix(uShade, uFoam, clamp(n * 0.9 + along * 0.4, 0.0, 1.0));
  gl_FragColor = vec4(col, a * 0.92);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}
`;

export function createWake({ length = 128, interval = 0.04 }) {
  const pts = [];
  const positions = new Float32Array(length * 2 * 3);
  const ages = new Float32Array(length * 2);
  const sides = new Float32Array(length * 2);
  const indices = [];

  for (let i = 0; i < length; i++) {
    const age = i / (length - 1);
    ages[i * 2] = age;
    ages[i * 2 + 1] = age;
    sides[i * 2] = -1;
    sides[i * 2 + 1] = 1;
    if (i < length - 1) {
      const a = i * 2;
      indices.push(a, a + 1, a + 2, a + 1, a + 3, a + 2);
    }
  }

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute("position", new THREE.BufferAttribute(positions, 3));
  geometry.setAttribute("aAge", new THREE.BufferAttribute(ages, 1));
  geometry.setAttribute("aSide", new THREE.BufferAttribute(sides, 1));
  geometry.setIndex(indices);
  geometry.boundingSphere = new THREE.Sphere(new THREE.Vector3(), 80);

  const material = new THREE.ShaderMaterial({
    uniforms: {
      uTime: { value: 0 },
      uFoam: { value: new THREE.Color("#f2fcff") },
      uShade: { value: new THREE.Color("#9fd8dc") },
    },
    vertexShader: WAKE_VERT,
    fragmentShader: WAKE_FRAG,
    transparent: true,
    depthWrite: false,
    side: THREE.DoubleSide,
  });

  const mesh = new THREE.Mesh(geometry, material);
  mesh.frustumCulled = false;
  mesh.renderOrder = 2;
  mesh.visible = false;

  let acc = 0;
  const _t = new THREE.Vector3();
  const _n = new THREE.Vector3();

  function update(dt, time, tailWorld, halfWidth) {
    acc += dt;
    if (acc >= interval) {
      acc = 0;
      pts.unshift({ x: tailWorld.x, z: tailWorld.z });
      if (pts.length > length) pts.length = length;
    }
    material.uniforms.uTime.value = time;
    if (pts.length < 4) return;
    mesh.visible = true;

    for (let i = 0; i < length; i++) {
      const k = Math.min(i, pts.length - 1);
      const p = pts[k];
      const age = pts.length > 1 ? i / (pts.length - 1) : 1;
      // direction along the trail
      const pn = pts[Math.max(0, k - 1)];
      const pp = pts[Math.min(pts.length - 1, k + 1)];
      _t.set(pn.x - pp.x, 0, pn.z - pp.z);
      if (_t.lengthSq() < 1e-8) _t.set(1, 0, 0);
      _t.normalize();
      // sideways on the water surface
      _n.set(-_t.z, 0, _t.x);
      const surf = oceanHeight(p.x, p.z, time);
      const w = lerp(halfWidth * 0.55, halfWidth * 3.1, Math.pow(clamp(age, 0, 1), 0.7));
      const y = surf + 0.014 + 0.02 * (1 - age);
      const i6 = i * 6;
      positions[i6] = p.x - _n.x * w;
      positions[i6 + 1] = y;
      positions[i6 + 2] = p.z - _n.z * w;
      positions[i6 + 3] = p.x + _n.x * w;
      positions[i6 + 4] = y;
      positions[i6 + 5] = p.z + _n.z * w;
    }
    geometry.attributes.position.needsUpdate = true;
    geometry.computeBoundingSphere();
  }

  return { mesh, material, update, clear: () => (pts.length = 0) };
}

/* --------------------------------------------------------- contact shadow */

export function createContactShadow({ texture }) {
  const mesh = new THREE.Mesh(
    new THREE.PlaneGeometry(1, 1),
    new THREE.MeshBasicMaterial({
      map: texture,
      color: new THREE.Color("#03222e"),
      transparent: true,
      opacity: 0.55,
      depthWrite: false,
    })
  );
  mesh.renderOrder = 1;
  mesh.frustumCulled = false;

  const up = new THREE.Vector3(0, 0, 1);
  const _n = new THREE.Vector3();

  function update(time, x, z, normal, sizeX, sizeZ, strength) {
    const surf = oceanHeight(x, z, time);
    mesh.position.set(x, surf + 0.02, z);
    _n.copy(normal);
    mesh.quaternion.setFromUnitVectors(up, _n);
    mesh.scale.set(sizeX, sizeZ, 1);
    mesh.material.opacity = strength;
  }

  return { mesh, update };
}

/* ------------------------------------------------------------- mist puffs */

/** Lazy drifting mist near the horizon so the sea does not look empty. */
export function createMist({ texture, count = 26 }) {
  const positions = new Float32Array(count * 3);
  const sizes = new Float32Array(count);
  const alphas = new Float32Array(count);
  const seeds = [];
  for (let i = 0; i < count; i++) {
    const a = Math.random() * Math.PI * 2;
    const r = 60 + Math.random() * 320;
    positions[i * 3] = Math.cos(a) * r;
    positions[i * 3 + 1] = 0.6 + Math.random() * 5.5;
    positions[i * 3 + 2] = Math.sin(a) * r;
    sizes[i] = 26 + Math.random() * 70;
    alphas[i] = 0.05 + Math.random() * 0.13;
    seeds.push({ sp: 0.4 + Math.random() * 1.4, ph: Math.random() * 10, x: positions[i * 3], z: positions[i * 3 + 2], y: positions[i * 3 + 1] });
  }
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute("position", new THREE.BufferAttribute(positions, 3));
  geometry.setAttribute("aSize", new THREE.BufferAttribute(sizes, 1));
  geometry.setAttribute("aAlpha", new THREE.BufferAttribute(alphas, 1));
  geometry.boundingSphere = new THREE.Sphere(new THREE.Vector3(), 600);

  const material = new THREE.ShaderMaterial({
    uniforms: {
      uTex: { value: texture },
      uScale: { value: 600 },
      uTint: { value: new THREE.Color("#ffe6c4") },
    },
    vertexShader: SPRAY_VERT,
    fragmentShader: SPRAY_FRAG,
    transparent: true,
    depthWrite: false,
  });
  const points = new THREE.Points(geometry, material);
  points.frustumCulled = false;
  points.renderOrder = 0;

  function update(dt, time) {
    for (let i = 0; i < count; i++) {
      const s = seeds[i];
      positions[i * 3] = s.x + Math.sin(time * 0.02 * s.sp + s.ph) * 12;
      positions[i * 3 + 1] = s.y + Math.sin(time * 0.05 + s.ph) * 0.8;
      positions[i * 3 + 2] = s.z + Math.cos(time * 0.017 * s.sp + s.ph) * 12;
    }
    geometry.attributes.position.needsUpdate = true;
  }

  return {
    points,
    material,
    update,
    setScale(h, fov) {
      material.uniforms.uScale.value = h / (2 * Math.tan((fov * Math.PI) / 360));
    },
  };
}

import * as THREE from "three";
import { lerp } from "./util.js";

function gullGeometry() {
  const s = new THREE.Shape();
  s.moveTo(0, 0.055);
  s.bezierCurveTo(0.18, 0.075, 0.42, 0.03, 0.62, -0.05);
  s.lineTo(0.6, -0.13);
  s.bezierCurveTo(0.38, -0.06, 0.16, -0.06, 0.0, -0.1);
  s.closePath();
  const g = new THREE.ShapeGeometry(s, 10);
  g.rotateX(-Math.PI / 2); // flat in XZ, span along +X, chord along +Z
  return g;
}

/** A loose flock wheeling in the distance — pure set dressing. */
export function createGulls(count = 7) {
  const group = new THREE.Group();

  const bodyMat = new THREE.MeshStandardMaterial({
    color: new THREE.Color("#f4f1ea"),
    roughness: 0.85,
    side: THREE.DoubleSide,
  });
  const tipMat = new THREE.MeshStandardMaterial({
    color: new THREE.Color("#4a4a52"),
    roughness: 0.8,
    side: THREE.DoubleSide,
  });

  const wingGeo = gullGeometry();
  const tipGeo = new THREE.PlaneGeometry(0.1, 0.1);
  tipGeo.rotateX(-Math.PI / 2);

  const birds = [];
  for (let i = 0; i < count; i++) {
    const b = new THREE.Group();
    const body = new THREE.Mesh(new THREE.SphereGeometry(0.085, 14, 10), bodyMat);
    body.scale.set(1.9, 0.85, 0.75);
    b.add(body);
    const beak = new THREE.Mesh(new THREE.ConeGeometry(0.026, 0.12, 8), tipMat);
    beak.rotation.z = -Math.PI / 2;
    beak.position.set(0.19, 0.01, 0);
    b.add(beak);

    const wings = [];
    for (const side of [1, -1]) {
      const w = new THREE.Group();
      w.position.set(0, 0.01, side * 0.05);
      const mesh = new THREE.Mesh(wingGeo, bodyMat);
      mesh.scale.z = side;
      w.add(mesh);
      const tip = new THREE.Mesh(tipGeo, tipMat);
      tip.position.set(0.56, 0.005, side * 0.075);
      tip.scale.z = side;
      w.add(tip);
      b.add(w);
      wings.push(w);
    }

    const a = (i / count) * Math.PI * 2 + Math.random();
    b.scale.setScalar(0.8 + Math.random() * 0.9);
    group.add(b);
    birds.push({
      obj: b,
      wings,
      radius: 26 + Math.random() * 46,
      height: 7 + Math.random() * 13,
      speed: (0.055 + Math.random() * 0.05) * (Math.random() < 0.25 ? -1 : 1),
      phase: a,
      flapSpeed: 3.4 + Math.random() * 2.2,
      flapPhase: Math.random() * 10,
      glide: Math.random() * 6,
      cx: (Math.random() - 0.5) * 30,
      cz: (Math.random() - 0.5) * 30,
      bob: 0.6 + Math.random() * 1.4,
    });
  }

  function update(t) {
    for (const bird of birds) {
      const a = bird.phase + t * bird.speed;
      const r = bird.radius + Math.sin(t * 0.11 + bird.phase) * 5;
      const x = bird.cx + Math.cos(a) * r;
      const z = bird.cz + Math.sin(a) * r * 0.72;
      const y = bird.height + Math.sin(t * 0.23 + bird.phase * 2) * bird.bob;
      bird.obj.position.set(x, y, z);
      // heading + a bank into the turn
      bird.obj.rotation.y = -a + (bird.speed > 0 ? Math.PI / 2 : -Math.PI / 2);
      bird.obj.rotation.x = Math.sign(bird.speed) * 0.3;
      bird.obj.rotation.z = Math.sin(t * 0.4 + bird.phase) * 0.08;

      const glide = Math.sin(t * 0.13 + bird.glide);
      const flap = Math.sin(t * bird.flapSpeed + bird.flapPhase) * (0.35 + 0.65 * Math.max(0, glide));
      bird.wings[0].rotation.x = -flap * 0.85;
      bird.wings[1].rotation.x = flap * 0.85;
      bird.wings[0].rotation.y = lerp(0, -0.25, Math.max(0, -glide));
      bird.wings[1].rotation.y = lerp(0, -0.25, Math.max(0, -glide));
    }
  }

  return { group, update };
}

import * as THREE from "three";

/** Flat wing in the XZ plane: chord along X, tip toward +Z, normal up. */
function gullWingGeometry() {
  const s = new THREE.Shape();
  s.moveTo(0.085, 0.0);
  s.bezierCurveTo(0.1, 0.2, 0.05, 0.44, -0.05, 0.63);
  s.lineTo(-0.135, 0.61);
  s.bezierCurveTo(-0.06, 0.4, -0.055, 0.18, -0.1, 0.0);
  s.closePath();
  const g = new THREE.ShapeGeometry(s, 10);
  g.rotateX(-Math.PI / 2); // shape-x -> +X (chord), shape-y -> -Z (span)
  g.scale(1, 1, -1); // span toward +Z
  return g;
}

/** A loose flock wheeling in the distance — pure set dressing. */
export function createGulls(count = 7) {
  const group = new THREE.Group();

  const bodyMat = new THREE.MeshStandardMaterial({
    color: new THREE.Color("#f6f3ec"),
    roughness: 0.85,
    side: THREE.DoubleSide,
  });
  const darkMat = new THREE.MeshStandardMaterial({
    color: new THREE.Color("#4b4b53"),
    roughness: 0.8,
    side: THREE.DoubleSide,
  });

  const wingGeo = gullWingGeometry();
  const tipGeo = new THREE.PlaneGeometry(0.13, 0.09);
  tipGeo.rotateX(-Math.PI / 2);
  const bodyGeo = new THREE.SphereGeometry(0.085, 14, 10);
  const beakGeo = new THREE.ConeGeometry(0.026, 0.13, 8);
  beakGeo.rotateZ(-Math.PI / 2);

  const birds = [];
  for (let i = 0; i < count; i++) {
    const b = new THREE.Group();

    const body = new THREE.Mesh(bodyGeo, bodyMat);
    body.scale.set(1.9, 0.85, 0.75);
    b.add(body);
    const beak = new THREE.Mesh(beakGeo, darkMat);
    beak.position.set(0.19, 0.012, 0);
    b.add(beak);
    const tail = new THREE.Mesh(tipGeo, bodyMat);
    tail.position.set(-0.2, 0.005, 0);
    tail.scale.set(1.1, 1, 0.55);
    b.add(tail);

    const wings = [];
    for (const side of [1, -1]) {
      const w = new THREE.Group();
      w.position.set(-0.01, 0.012, side * 0.045);
      w.scale.z = side; // -1 mirrors the port wing
      const mesh = new THREE.Mesh(wingGeo, bodyMat);
      w.add(mesh);
      const tip = new THREE.Mesh(tipGeo, darkMat);
      tip.position.set(-0.035, 0.004, 0.58);
      tip.scale.set(0.9, 1, 0.5);
      w.add(tip);
      b.add(w);
      wings.push({ group: w, side });
    }

    b.scale.setScalar(0.85 + Math.random() * 1.0);
    group.add(b);
    birds.push({
      obj: b,
      wings,
      radius: 24 + Math.random() * 48,
      height: 6.5 + Math.random() * 14,
      speed: (0.05 + Math.random() * 0.05) * (Math.random() < 0.3 ? -1 : 1),
      phase: (i / count) * Math.PI * 2 + Math.random(),
      flapSpeed: 3.2 + Math.random() * 2.4,
      flapPhase: Math.random() * 10,
      glidePhase: Math.random() * 6,
      cx: (Math.random() - 0.5) * 34,
      cz: (Math.random() - 0.5) * 34,
      squash: 0.55 + Math.random() * 0.4,
      bob: 0.5 + Math.random() * 1.5,
    });
  }

  function update(t) {
    for (const bird of birds) {
      const a = bird.phase + t * bird.speed;
      const r = bird.radius + Math.sin(t * 0.11 + bird.phase) * 5;
      const x = bird.cx + Math.cos(a) * r;
      const z = bird.cz + Math.sin(a) * r * bird.squash;
      const y = bird.height + Math.sin(t * 0.23 + bird.phase * 2) * bird.bob;
      bird.obj.position.set(x, y, z);

      // heading = d/da of the orbit, flipped when flying clockwise
      const dir = Math.sign(bird.speed);
      const hx = -Math.sin(a) * r * dir;
      const hz = Math.cos(a) * r * bird.squash * dir;
      bird.obj.rotation.y = Math.atan2(-hz, hx);
      bird.obj.rotation.x = dir * 0.32; // bank into the turn
      bird.obj.rotation.z = Math.sin(t * 0.37 + bird.phase) * 0.07;

      // flap, then hold a glide when the "glide" oscillator is negative
      const glide = Math.sin(t * 0.13 + bird.glidePhase);
      const amp = 0.22 + 0.78 * Math.max(0, glide);
      const flap = Math.sin(t * bird.flapSpeed + bird.flapPhase) * amp + 0.08 * glide;
      for (const w of bird.wings) {
        w.group.rotation.x = -w.side * flap * 0.9;
      }
    }
  }

  return { group, update };
}

import * as THREE from "three";
import { oceanHeight } from "./waves.js";
import { clamp, lerp, smoothstep } from "./util.js";
import { DECK_Y } from "./board.js";

const HL = 1.32; // probe half-distance along the board
const HW = 0.3; // probe half-distance across the board

/** Cinematic "path" the pelican carves across the swell. */
function pathPos(t, out) {
  out.x =
    5.4 * Math.sin(t * 0.13) + 1.7 * Math.sin(t * 0.31 + 1.7) + 0.55 * Math.sin(t * 0.61 + 0.4);
  out.z = 3.1 * Math.sin(t * 0.095 + 0.6) + 1.1 * Math.sin(t * 0.23 + 2.3);
  return out;
}

export function createSurfer({ rig, pelican, spray, wake, shadow }) {
  const pelicanRoot = pelican.root;
  pelicanRoot.position.y = DECK_Y;
  rig.add(pelicanRoot);

  const _p = { x: 0, z: 0 };
  const _pA = { x: 0, z: 0 };
  const _pB = { x: 0, z: 0 };
  const fwd = new THREE.Vector3(1, 0, 0);
  const right = new THREE.Vector3(0, 0, 1);
  const up = new THREE.Vector3(0, 1, 0);
  const surfUp = new THREE.Vector3(0, 1, 0);
  const basis = new THREE.Matrix4();
  const _tmp = new THREE.Vector3();

  const state = {
    yaw: 0,
    yawRate: 0,
    speed: 0,
    accel: 0,
    pitch: 0,
    roll: 0,
    y: 0,
    vy: 0,
    ay: 0,
    bank: 0,
    slip: 0,
  };

  let tailAcc = 0;
  let railAcc = 0;
  let noseCooldown = 0;
  let prevVy = 0;
  let prevSpeed = 0;
  let prevYaw = 0;
  let first = true;

  const tailWorld = new THREE.Vector3();
  const noseWorld = new THREE.Vector3();
  const railWorld = new THREE.Vector3();

  function surfacePoint(out, lx, ly, lz) {
    out
      .copy(rig.position)
      .addScaledVector(fwd, lx)
      .addScaledVector(up, ly)
      .addScaledVector(right, lz);
    return out;
  }

  function update(t, dt) {
    dt = Math.min(dt, 0.05);

    /* ---- where the board is going --------------------------------- */
    const eps = 0.06;
    pathPos(t, _p);
    pathPos(t + eps, _pA);
    pathPos(t - eps, _pB);
    const vx = (_pA.x - _pB.x) / (2 * eps);
    const vz = (_pA.z - _pB.z) / (2 * eps);
    const speed = Math.hypot(vx, vz);

    // the board points mostly where it is going, with a carving slip angle
    const slip = 0.2 * Math.sin(t * 0.37) + 0.12 * Math.sin(t * 0.19 + 2.0);
    let heading = Math.atan2(vz, vx) + slip;

    // smooth the heading so the nose never snaps
    if (first) {
      state.yaw = heading;
      first = false;
    } else {
      let d = heading - state.yaw;
      while (d > Math.PI) d -= Math.PI * 2;
      while (d < -Math.PI) d += Math.PI * 2;
      state.yaw += d * (1 - Math.exp(-6 * dt));
    }
    const yawRate = (state.yaw - prevYaw) / Math.max(dt, 1e-4);
    prevYaw = state.yaw;

    /* ---- sample the sea under the board ---------------------------- */
    const cosY = Math.cos(state.yaw);
    const sinY = Math.sin(state.yaw);
    fwd.set(cosY, 0, sinY);
    right.set(-sinY, 0, cosY);

    const cx = _p.x;
    const cz = _p.z;
    const hC = oceanHeight(cx, cz, t);
    const hN = oceanHeight(cx + fwd.x * HL, cz + fwd.z * HL, t);
    const hT = oceanHeight(cx - fwd.x * HL, cz - fwd.z * HL, t);
    const hR = oceanHeight(cx + right.x * HW, cz + right.z * HW, t);
    const hL = oceanHeight(cx - right.x * HW, cz - right.z * HW, t);
    const gF = (hN - hT) / (2 * HL);
    const gR = (hR - hL) / (2 * HW);

    // plane-fit normal, then a carve bank on top of it
    surfUp.set(-gF * fwd.x - gR * right.x, 1, -gF * fwd.z - gR * right.z).normalize();

    const targetBank = clamp(yawRate * 1.15, -0.55, 0.55) + 0.05 * Math.sin(t * 0.83);
    state.bank = lerp(state.bank, targetBank, 1 - Math.exp(-3.2 * dt));

    // rotate surfUp around fwd by the bank angle
    _tmp.copy(right).multiplyScalar(Math.cos(state.bank)).addScaledVector(surfUp, Math.sin(state.bank));
    // (right tilts down into the turn, up tilts with it)
    up.copy(surfUp).multiplyScalar(Math.cos(state.bank)).addScaledVector(right, -Math.sin(state.bank));
    right.copy(_tmp).cross(up).normalize();
    fwd.copy(up).cross(right).normalize();

    // planing: nose rides a touch high, pumping with the swell
    const pump = 0.05 * Math.sin(t * 1.62) + 0.03 * Math.sin(t * 2.7 + 1.1);
    _tmp.copy(fwd).applyAxisAngle(right, pump + 0.035);
    fwd.copy(_tmp);
    up.cross(right).copy(fwd).cross(right); // rebuild orthonormal up
    up.crossVectors(right, fwd).normalize();
    // re-orthogonalise right
    right.crossVectors(fwd, up).normalize();

    basis.makeBasis(fwd, up, right);
    rig.quaternion.setFromRotationMatrix(basis);

    /* ---- vertical ride --------------------------------------------- */
    const float = 0.045 + 0.03 * Math.sin(t * 1.62 + 0.9) + 0.05 * speed * 0.2;
    const y = hC + float;
    const vy = (y - state.y) / Math.max(dt, 1e-4);
    const ay = (vy - prevVy) / Math.max(dt, 1e-4);
    prevVy = vy;
    rig.position.set(cx, y, cz);

    /* ---- derived motion cues --------------------------------------- */
    state.speed = speed;
    state.accel = (speed - prevSpeed) / Math.max(dt, 1e-4);
    prevSpeed = speed;
    state.yawRate = yawRate;
    state.pitch = Math.asin(clamp(fwd.y, -1, 1));
    state.roll = Math.asin(clamp(-right.y, -1, 1));
    state.vy = vy;
    state.ay = ay;
    state.y = y;
    state.slip = slip;

    pelican.update(t, dt, {
      pitch: state.pitch,
      roll: state.roll,
      heave: clamp(ay * 0.05, -0.5, 0.5),
      accelX: clamp(state.accel * 0.6, -1.2, 1.2),
      yawRate: clamp(yawRate, -1.5, 1.5),
      speed,
    });

    /* ---- foam: wake, contact shadow, spray -------------------------- */
    surfacePoint(tailWorld, -1.5, -DECK_Y, 0);
    surfacePoint(noseWorld, 1.55, -DECK_Y, 0);
    const inside = Math.sign(state.bank) || 1;
    surfacePoint(railWorld, -0.15, -DECK_Y, inside * 0.34);

    if (wake) wake.update(dt, t, tailWorld, 0.34);
    if (shadow) {
      shadow.update(t, cx, cz, surfUp, 4.1, 1.5, clamp(0.5 - float * 1.6, 0.18, 0.5));
    }

    if (spray) {
      const chop = Math.abs(gF) + Math.abs(gR);
      // tail wash — a steady rope of droplets off the back of the board
      tailAcc += dt * (26 + speed * 46 + chop * 90);
      while (tailAcc >= 1) {
        tailAcc -= 1;
        const side = Math.random() - 0.5;
        spray.emit({
          x: tailWorld.x + (Math.random() - 0.5) * 0.3,
          y: Math.max(tailWorld.y, oceanHeight(tailWorld.x, tailWorld.z, t)) + 0.02,
          z: tailWorld.z + (Math.random() - 0.5) * 0.3,
          dx: -fwd.x * 0.55 + right.x * side * 0.5,
          dy: 0.42 + Math.random() * 0.3,
          dz: -fwd.z * 0.55 + right.z * side * 0.5,
          spread: 0.5,
          speed: 0.9 + speed * 0.85 + Math.random() * 0.7,
          size: 0.045 + Math.random() * 0.09,
          life: 0.75 + Math.random() * 0.7,
        });
      }

      // rail spray — the fan thrown off the inside rail through a hard carve
      const carve = smoothstep(0.16, 0.6, Math.abs(yawRate)) * (0.6 + speed * 0.5);
      railAcc += dt * carve * 120;
      while (railAcc >= 1) {
        railAcc -= 1;
        spray.emit({
          x: railWorld.x + (Math.random() - 0.5) * 0.9,
          y: Math.max(railWorld.y, oceanHeight(railWorld.x, railWorld.z, t)) + 0.03,
          z: railWorld.z + (Math.random() - 0.5) * 0.9,
          dx: right.x * inside * 0.9 + fwd.x * -0.25,
          dy: 0.5 + Math.random() * 0.45,
          dz: right.z * inside * 0.9 + fwd.z * -0.25,
          spread: 0.45,
          speed: 1.6 + carve * 3.4 + Math.random() * 1.2,
          size: 0.05 + Math.random() * 0.13,
          life: 0.7 + Math.random() * 0.8,
          alpha: 0.85,
        });
      }

      // nose impact — when the board slams down into the trough
      noseCooldown -= dt;
      const slam = -ay * 0.06 - state.pitch * 1.4;
      if (noseCooldown <= 0 && slam > 0.42) {
        noseCooldown = 0.42 + Math.random() * 0.5;
        const n = 14 + Math.floor(Math.random() * 12);
        for (let i = 0; i < n; i++) {
          const side = (Math.random() - 0.5) * 2;
          spray.emit({
            x: noseWorld.x + (Math.random() - 0.5) * 0.35,
            y: Math.max(noseWorld.y, oceanHeight(noseWorld.x, noseWorld.z, t)) + 0.02,
            z: noseWorld.z + (Math.random() - 0.5) * 0.35,
            dx: fwd.x * 0.55 + right.x * side * 0.85,
            dy: 0.62 + Math.random() * 0.5,
            dz: fwd.z * 0.55 + right.z * side * 0.85,
            spread: 0.6,
            speed: 1.4 + Math.random() * 2.6,
            size: 0.07 + Math.random() * 0.17,
            life: 0.8 + Math.random() * 0.9,
          });
        }
      }
      spray.update(dt, t);
    }
  }

  return {
    rig,
    update,
    state,
    get tailWorld() {
      return tailWorld;
    },
  };
}

