/* Dev-only smoke test: builds every non-DOM module and steps the simulation. */
import * as THREE from "three";
import { createOceanGeometry } from "./src/ocean.js";
import { OCEAN_GLSL, oceanHeight, oceanSlope, MAX_HEIGHT } from "./src/waves.js";
import { createBoard, deckHeightAt } from "./src/board.js";
import { createPelican } from "./src/pelican.js";
import { createSurfer } from "./src/surfer.js";
import { createGulls } from "./src/gulls.js";
import { createCameraRig } from "./src/camera.js";
import { createSpray, createWake, createContactShadow, createMist } from "./src/foam.js";

const problems = [];
const checkFinite = (label, obj) => {
  const nums = [];
  obj.traverse((o) => {
    nums.push(o.position.x, o.position.y, o.position.z);
    nums.push(o.quaternion.x, o.quaternion.y, o.quaternion.z, o.quaternion.w);
    nums.push(o.scale.x, o.scale.y, o.scale.z);
  });
  if (nums.some((n) => !Number.isFinite(n))) problems.push(`NaN/Inf in ${label}`);
};

/* ---- ocean grid ---- */
const og = createOceanGeometry();
console.log(
  "ocean grid: verts",
  og.attributes.position.count,
  "tris",
  og.index.count / 3,
  "radius",
  og.boundingSphere.radius
);

/* ---- wave field ---- */
let hmin = Infinity;
let hmax = -Infinity;
let smax = 0;
for (let i = 0; i < 4000; i++) {
  const x = (Math.random() - 0.5) * 200;
  const z = (Math.random() - 0.5) * 200;
  const t = Math.random() * 200;
  const h = oceanHeight(x, z, t);
  const s = oceanSlope(x, z, t, [0, 0]);
  hmin = Math.min(hmin, h);
  hmax = Math.max(hmax, h);
  smax = Math.max(smax, Math.hypot(s[0], s[1]));
}
console.log("waves: h range", hmin.toFixed(3), hmax.toFixed(3), "declared max", MAX_HEIGHT.toFixed(3), "max slope", smax.toFixed(3));

const speeds = [];
for (let t = 0; t < 40; t += 0.25) {
  speeds.push(oceanHeight(3.1, 7.7, t + 0.25) - oceanHeight(3.1, 7.7, t));
}
console.log("glsl preview:\n" + OCEAN_GLSL.split("\n").slice(0, 6).join("\n") + "\n...");

/* ---- board ---- */
const board = createBoard({ speckleTex: null });
board.group.updateMatrixWorld(true);
const bb = new THREE.Box3().setFromObject(board.group);
console.log("board bbox", bb.min.toArray().map((v) => v.toFixed(3)).join(","), "->", bb.max.toArray().map((v) => v.toFixed(3)).join(","));
console.log("deck height at 0.3/-0.5/-1.4:", deckHeightAt(0.3).toFixed(4), deckHeightAt(-0.5).toFixed(4), deckHeightAt(-1.4).toFixed(4));

/* ---- pelican ---- */
const pelican = createPelican({ featherTex: null });
pelican.root.updateMatrixWorld(true);
const pb = new THREE.Box3().setFromObject(pelican.root);
console.log("pelican bbox", pb.min.toArray().map((v) => v.toFixed(3)).join(","), "->", pb.max.toArray().map((v) => v.toFixed(3)).join(","));
let tris = 0;
pelican.root.traverse((o) => {
  if (o.isMesh) tris += (o.geometry.index ? o.geometry.index.count : o.geometry.attributes.position.count) / 3;
});
console.log("pelican triangles", tris | 0);

/* ---- surfer + foam + camera, 1200 steps ---- */
const rig = new THREE.Group();
rig.add(board.group);
let emitted = 0;
const sprayStub = {
  emit() {
    emitted++;
  },
  update() {},
};
const wake = createWake({ length: 132, interval: 0.04 });
const shadow = createContactShadow({ texture: null });
const surfer = createSurfer({ rig, pelican, spray: sprayStub, wake, shadow });
const camera = new THREE.PerspectiveCamera(42, 16 / 9, 0.18, 4200);
const camRig = createCameraRig(camera);
const gulls = createGulls(5);

const dt = 1 / 60;
let t = 21.7;
const speedsBoard = [];
let minY = Infinity;
let maxY = -Infinity;
for (let i = 0; i < 3600; i++) {
  t += dt;
  surfer.update(t, dt);
  wake.update(dt, t, surfer.tailWorld, 0.34);
  shadow.update(t, rig.position.x, rig.position.z, new THREE.Vector3(0, 1, 0), 4, 1.4, 0.4);
  camRig.update(t, dt, rig.position, { speed: surfer.state.speed, forward: surfer.state.forward });
  gulls.update(t);
  speedsBoard.push(surfer.state.speed);
  minY = Math.min(minY, rig.position.y);
  maxY = Math.max(maxY, rig.position.y);
  if (i % 400 === 0) {
    checkFinite("rig", rig);
    checkFinite("pelican", pelican.root);
    checkFinite("gulls", gulls.group);
    if (!Number.isFinite(camera.position.x + camera.position.y + camera.position.z)) problems.push("NaN camera");
  }
}
console.log(
  "board: speed",
  Math.min(...speedsBoard).toFixed(2),
  "-",
  Math.max(...speedsBoard).toFixed(2),
  "| y",
  minY.toFixed(2),
  maxY.toFixed(2),
  "| pitch",
  surfer.state.pitch.toFixed(3),
  "| roll",
  surfer.state.roll.toFixed(3),
  "| droplets emitted",
  emitted
);
console.log("camera at", camera.position.toArray().map((v) => v.toFixed(2)).join(","), "fov", camera.fov.toFixed(2));

/* ---- wake geometry sanity ---- */
const wp = wake.mesh.geometry.attributes.position.array;
console.log("wake verts", wp.length / 3, "finite", Array.from(wp).every(Number.isFinite));

/* ---- spray/mist with real buffers ---- */
const spray = createSpray({ texture: null, count: 200 });
const mist = createMist({ texture: null, count: 8 });
for (let i = 0; i < 60; i++) {
  spray.emit({ x: 0, y: 0, z: 0, dx: 1, dy: 1, dz: 0, spread: 0.5, speed: 2, size: 0.1, life: 1 });
  spray.update(dt, t);
}
mist.update(dt, t);
console.log("spray positions finite", Array.from(spray.points.geometry.attributes.position.array).every(Number.isFinite));

if (problems.length) {
  console.error("PROBLEMS:", problems);
  process.exit(1);
}
console.log("smoke test OK");

