#!/usr/bin/env node
/* Dev-only preview harness: bundles main.js, renders it in headless Chrome
 * (SwiftShader) and dumps console output + screenshots. Not part of the page. */
import { execFileSync } from "node:child_process";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import puppeteer from "puppeteer-core";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const out = resolve(root, ".preview");
mkdirSync(out, { recursive: true });

execFileSync(
  resolve(root, "node_modules/.bin/esbuild"),
  ["main.js", "--bundle", "--format=esm", `--outfile=${out}/bundle.js`, "--log-level=warning"],
  { cwd: root, stdio: "inherit" }
);

const html = readFileSync(resolve(root, "index.html"), "utf8").replace(
  'src="main.js"',
  'src="bundle.js"'
);
writeFileSync(resolve(out, "index.html"), html);

const browser = await puppeteer.launch({
  executablePath: "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
  headless: "new",
  args: [
    "--no-sandbox",
    "--enable-unsafe-swiftshader",
    "--use-gl=angle",
    "--use-angle=swiftshader",
    "--window-size=1280,720",
    "--hide-scrollbars",
  ],
});

const page = await browser.newPage();
await page.setViewport({ width: 1280, height: 720, deviceScaleFactor: 1 });

const logs = [];
page.on("console", (m) => logs.push(`[${m.type()}] ${m.text()}`));
page.on("pageerror", (e) => logs.push(`[pageerror] ${e.message}\n${e.stack || ""}`));
page.on("requestfailed", (r) => logs.push(`[requestfailed] ${r.url()}`));

await page.goto(`file://${out}/index.html`, { waitUntil: "load", timeout: 60000 });

const info = await page.evaluate(() => {
  const c = document.createElement("canvas");
  const gl = c.getContext("webgl2");
  if (!gl) return { webgl: false };
  const dbg = gl.getExtension("WEBGL_debug_renderer_info");
  return {
    webgl: true,
    renderer: dbg ? gl.getParameter(dbg.UNMASKED_RENDERER_WEBGL) : gl.getParameter(gl.RENDERER),
    version: gl.getParameter(gl.VERSION),
  };
});
console.log("WEBGL:", JSON.stringify(info));

const marks = [3, 9, 16, 24, 34, 46];
let prev = 0;
for (let i = 0; i < marks.length; i++) {
  await new Promise((r) => setTimeout(r, (marks[i] - prev) * 1000));
  prev = marks[i];
  const frames = await page.evaluate(
    () => (window.__surf ? { t: window.__surf.t, frames: window.__surf.frames } : null)
  );
  await page.screenshot({ path: resolve(out, `shot-${String(marks[i]).padStart(2, "0")}.png`) });
  console.log(`shot @${marks[i]}s real ->`, JSON.stringify(frames));
}

await browser.close();
console.log("---- console ----");
console.log(logs.slice(0, 80).join("\n") || "(clean)");

